fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // Promote to a slightly larger signed type for intermediate arithmetic
    let a = a as i16;
    let b = b as i16;
    let f = f as i16;
    let k = k as i16;

    // Current position: 0 means at the "start" endpoint,  a means at the "far" endpoint.
    let mut cur_pos = 0i16;
    // Start with a full tank
    let mut fuel = b;
    // Count how many times we actually refuel at the station
    let mut refuels = 0;

    // We perform exactly k one‐way legs
    let mut leg = 0;
    while leg < k {
        leg += 1;

        // Determine where the station is and where we're headed this leg
        let (station_pos, dest) = if cur_pos == 0 {
            // going from 0 → a
            (f, a)
        } else {
            // going from a → 0
            (a - f, 0)
        };

        // 1) drive from current position to the station
        let d1 = (station_pos - cur_pos).abs();
        if fuel < d1 {
            // cannot even reach the station
            return -1;
        }
        fuel -= d1;
        cur_pos = station_pos;

        // 2) from the station we must eventually reach 'dest'; 
        //    if there are more legs after this one, we must also be able
        //    to go from 'dest' to the next station without refueling at the endpoint.
        let d2 = (dest - station_pos).abs();
        let d3 = if leg < k {
            // next leg's station
            let next_station = if dest == 0 { f } else { a - f };
            (next_station - dest).abs()
        } else {
            0
        };

        let needed = d2 + d3;
        // If our remaining fuel is not enough for (d2 + d3), we must top up here
        if fuel < needed {
            // fill to capacity
            refuels += 1;
            fuel = b;
            // if still not enough, impossible
            if fuel < needed {
                return -1;
            }
        }

        // 3) actually drive to dest
        fuel -= d2;
        cur_pos = dest;
        // endpoints do not allow refuel, so we carry over whatever fuel remains
    }

    // If we never refueled at the station, return 0; otherwise 1
    if refuels == 0 { 0 } else { 1 }
}

